KG42.register("clusters-3331a1ec8e29688fdd3c52e5",{"id":"05-double_auction::v142-d-CL005","paper":"05-double_auction","label":"Scope of local tradability of prosumer surplus electricity within the case study","record":{"cluster_id":"v142-d-CL005","label":"Scope of local tradability of prosumer surplus electricity within the case study","market_meaning":"In the microgrid under study, surplus solar electricity serves as the product submitted in kWh; in the described case with 70 consumers and 30 prosumers, the prosumers' surplus electricity is available for neighborhood trading within the specified illustrative time window.","mechanism_ids":["v141-a-M01"],"market_types":["LEM"],"process_stages":["participation","bidding","activation"],"scope_disposition":"conditional","scope_explanation":"The product definition covers the microgrid under study, while the prosumer composition and the time window of approximately 07:30 to 16:00 belong only to the cited case. The illustrative surplus-electricity time window must not be elevated to a universal entry threshold or a mandatory trading period.","assembly_status":"assembled","boundary_rationale":"The supplying entities, surplus-electricity product, and scope of local tradability jointly define what may be submitted for trading and have independent market meaning; this does not include generation modeling or price conditions for winning trades.","chain_bindings":[{"chain_id":"v141-c-R010","ownership":"primary","role":"core","rationale":"Defines the surplus-electricity product, the measurement unit for submissions, and the trading scope of the case study."},{"chain_id":"v141-c-R008","ownership":"primary","role":"core","rationale":"Adds the prosumer entities that supply surplus electricity in this case study."},{"chain_id":"v141-c-R006","ownership":"shared","role":"context","rationale":"Shares only the case-study trading description in C004; the general execution-price conditions do not become participation dependencies of this cluster, and its primary assignment is to CL004."}],"connections":[{"connection_id":"v142-d-CL005-L01","from_chain_id":"v141-c-R008","to_chain_id":"v141-c-R010","kind":"complementary_scope","from_refs":["v141-c-R008::phi::v141-c-R008-C001"],"to_refs":["v141-c-R010::phi::v141-c-R010-C002"],"evidence_ids":["v141-b-g02-E24"],"rationale":"The same case explicitly identifies prosumers as providing surplus electricity tradable within the neighborhood; the supplying entities and product scope are complementary and do not yield a general eligibility judgment."},{"connection_id":"v142-d-CL005-L02","from_chain_id":"v141-c-R010","to_chain_id":"v141-c-R006","kind":"alternative_representation","from_refs":["v141-c-R010::phi::v141-c-R010-C002"],"to_refs":["v141-c-R006::phi::v141-c-R006-C004"],"evidence_ids":["v141-b-g02-E24"],"rationale":"Both occurrences carry the same description of surplus-electricity tradability in the case study, attached respectively to the product and execution functions; they are retained as related representations and are not counted as two independent market permissions."}],"object_mappings":[{"mapping_id":"v142-d-CL005-O01","kind":"alternative_representation","member_refs":["v141-c-R010::phi::v141-c-R010-C002","v141-c-R006::phi::v141-c-R006-C004"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-E24"],"rationale":"These are two representations assigning the tradability scope of the same case study to different functions; their member nodes differ, and they are not formalized. All originals are retained, and they are not selected as interchangeable constraints."}],"gaps":[{"gap_id":"v142-d-CL005-G01","category":"scope_conflict","description":"The wording of the 30% proportion in the case study does not specify its denominator and needs to be checked against the counts of 70 consumers and 30 prosumers; the existing chain also lacks a generalized surplus-electricity threshold or eligibility criterion.","chain_ids":["v141-c-R008","v141-c-R010","v141-c-R006"],"object_refs":["v141-c-R008::phi::v141-c-R008-C001","v141-c-R010::phi::v141-c-R010-C002","v141-c-R006::phi::v141-c-R006-C004"],"evidence_ids":["v141-b-g02-E24"],"proposal_ids":[],"required_work":"Verify the case-study proportion, figures, and time window; if a general entry rule is needed, obtain separate evidence and have C model it, rather than deriving it from the case description."},{"gap_id":"v142-d-CL005-G02","category":"unverified_source","description":"The product and case-study scope are supported only by unreviewed B texts; assembled indicates only that the stated case-study semantics can be assembled.","chain_ids":["v141-c-R008","v141-c-R010","v141-c-R006"],"object_refs":[],"evidence_ids":["v141-b-g01-ev-13","v141-b-g02-E17","v141-b-g02-E24"],"proposal_ids":[],"required_work":"Independently verify the product statement and the original case-study figures and text, without treating descriptive numbers as validated parameters."}]},"rule_refs":["05-double_auction::v141-c-R010","05-double_auction::v141-c-R008","05-double_auction::v141-c-R006"],"unresolved_rule_refs":[],"node_ids":["COMP-230dbf46f02b4bfe","COMP-d3b88931c4051195","KG31-58074c71e4394ab8","KG31-69ba805a251afd65"]});
